import{_ as t,c as i,o as a,a3 as r}from"./chunks/framework.Dhzub2q0.js";const p=JSON.parse('{"title":"Vilinko Studio Paid Service Agreement","description":"","frontmatter":{},"headers":[],"relativePath":"en/agreement/pay.md","filePath":"en/agreement/pay.md"}'),o={name:"en/agreement/pay.md"};function n(s,e,l,c,d,h){return a(),i("div",null,e[0]||(e[0]=[r('<h1 id="vilinko-studio-paid-service-agreement" tabindex="-1">Vilinko Studio Paid Service Agreement <a class="header-anchor" href="#vilinko-studio-paid-service-agreement" aria-label="Permalink to &quot;Vilinko Studio Paid Service Agreement&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Version</p><p>Initial release date: August 6, 2025</p><p>Last updated date: August 6, 2025</p></div><p>In case of any conflict, the <a href="/agreement/pay.html"><strong>Simplified Chinese version</strong></a> shall prevail.</p><h2 id="_1-scope-and-definitions-of-the-agreement" tabindex="-1">1. Scope and Definitions of the Agreement <a class="header-anchor" href="#_1-scope-and-definitions-of-the-agreement" aria-label="Permalink to &quot;1. Scope and Definitions of the Agreement&quot;">​</a></h2><ul><li>This agreement is a legally binding agreement between you (the user) and Vilinko Studio (hereinafter referred to as &quot;we&quot;) regarding the use of paid information technology tools and related services (hereinafter referred to as &quot;paid services&quot;) provided by Vilinko Studio.</li><li>Paid services include but are not limited to: &quot;LightFrame&quot; software customization services (for details, see <a href="/docs/lightframe/index.html">LightFrame</a>, premium membership services, value-added function modules, exclusive technical support, etc.</li><li>This agreement is a supplementary agreement to the &quot;Vilinko Studio Software Service Agreement&quot; and has the same legal effect as the main agreement. If there is any inconsistency between this agreement and the main agreement, this agreement shall prevail.</li><li>Your purchase or use of any paid service shall be deemed as your having read, understood and agreed to all the terms of this agreement.</li></ul><h2 id="_2-content-and-price-of-paid-services" tabindex="-1">2. Content and Price of Paid Services <a class="header-anchor" href="#_2-content-and-price-of-paid-services" aria-label="Permalink to &quot;2. Content and Price of Paid Services&quot;">​</a></h2><ul><li>The specific content, function description, service period and corresponding price of paid services shall be subject to the service purchase page or relevant service description documents.</li><li>We reserve the right to adjust the price and content of paid services according to market conditions, but the already purchased services shall not be affected by such adjustments.</li><li>The content and price of &quot;LightFrame&quot; customization services shall be subject to the information published on the <a href="/docs/lightframe/index.html">LightFrame</a> page. If personalized customization services beyond the standard scope are required, both parties shall negotiate separately to determine.</li></ul><h2 id="_3-service-purchase-and-payment" tabindex="-1">3. Service Purchase and Payment <a class="header-anchor" href="#_3-service-purchase-and-payment" aria-label="Permalink to &quot;3. Service Purchase and Payment&quot;">​</a></h2><ul><li>You can purchase paid services through our official website, client or designated third-party platforms (including but not limited to Afadian platform).</li><li>The payment methods shall be subject to those displayed on the purchase page, and you shall complete the payment in accordance with the selected payment method.</li><li>After successful payment, we will activate the corresponding paid service within a reasonable time, and the service period shall be calculated from the date of activation.</li><li>If the service is not activated despite successful payment due to payment system failure, you can contact customer service for handling, and we will solve it in a timely manner after verification.</li></ul><h2 id="_4-service-usage-specifications" tabindex="-1">4. Service Usage Specifications <a class="header-anchor" href="#_4-service-usage-specifications" aria-label="Permalink to &quot;4. Service Usage Specifications&quot;">​</a></h2><ul><li>The paid services you purchase are limited to your own use or the use by the legal entity you represent, and shall not be transferred, rented, lent or shared to any third party unless you obtain our written permission.</li><li>You shall not use paid services for any illegal or irregular activities, and shall not infringe upon the legitimate rights and interests of any third party.</li><li>For &quot;LightFrame&quot; customization services, you shall provide necessary materials and information in accordance with the requirements in <a href="/docs/lightframe/index.html">LightFrame</a>. We shall not be liable for customization delays or inconsistent effects caused by incomplete or inaccurate information provided by you.</li></ul><h2 id="_5-refund-policy" tabindex="-1">5. Refund Policy <a class="header-anchor" href="#_5-refund-policy" aria-label="Permalink to &quot;5. Refund Policy&quot;">​</a></h2><ul><li>Except for the following circumstances, paid services are non-refundable once purchased: <ul><li>The paid service has major functional defects, and we cannot repair them within a reasonable period, affecting core usage;</li><li>Due to our reasons, you cannot use the purchased paid service, and no alternative solution can be provided;</li><li>Otherwise stipulated by laws and regulations.</li></ul></li><li>To apply for a refund, you need to contact customer service within 7 working days after discovering the problem and provide relevant supporting materials. We will review and handle it within 15 working days.</li><li>For services purchased through third-party platforms (such as Afadian), the refund policy may also be subject to the relevant regulations of the platform.</li></ul><h2 id="_6-service-changes-and-termination" tabindex="-1">6. Service Changes and Termination <a class="header-anchor" href="#_6-service-changes-and-termination" aria-label="Permalink to &quot;6. Service Changes and Termination&quot;">​</a></h2><ul><li>We reserve the right to make necessary updates and optimizations to paid services. If it involves major changes to the service content, we will notify you through official channels 7 days in advance.</li><li>If you violate the provisions of this agreement or the main agreement, we have the right to suspend or terminate the provision of paid services to you without refunding the paid fees.</li><li>After the expiration of the service period, if you do not renew, the paid service will be automatically terminated, and you will not be able to continue using the corresponding paid functions, but the free services will not be affected.</li></ul><h2 id="_7-intellectual-property-protection" tabindex="-1">7. Intellectual Property Protection <a class="header-anchor" href="#_7-intellectual-property-protection" aria-label="Permalink to &quot;7. Intellectual Property Protection&quot;">​</a></h2><ul><li>We own all intellectual property rights of all paid services and related software, codes and contents, unless otherwise explicitly stated.</li><li>Some software and codes are open-sourced on the GitHub platform and comply with corresponding open-source licenses (such as MIT, GPL, etc.), and your use shall also comply with the provisions of relevant open-source licenses.</li><li>For the output results of &quot;LightFrame&quot; customization services, unless otherwise agreed, you only obtain the right to use the results, and the relevant intellectual property rights still belong to us. If you need to obtain the transfer of intellectual property rights, a separate agreement shall be signed and corresponding fees shall be paid.</li><li>You shall not conduct reverse engineering, reverse compilation, disassembly or other similar acts on the software and codes related to paid services, and shall not arbitrarily modify, copy, disseminate or create derivative works.</li><li>The intellectual property rights of the content you upload or create in the process of using paid services belong to you, but you grant us the necessary right to use it to provide services.</li></ul><h2 id="_8-disclaimer" tabindex="-1">8. Disclaimer <a class="header-anchor" href="#_8-disclaimer" aria-label="Permalink to &quot;8. Disclaimer&quot;">​</a></h2><ul><li>Paid services are provided &quot;as is&quot;. We do not guarantee that the services are completely free of defects or uninterrupted, but will make every effort to ensure the stability of the services.</li><li>We shall not be liable for service interruptions or inability to use caused by force majeure, third-party service failures, your equipment or network problems, etc., but will try our best to assist in solving them.</li><li>You understand and agree that the risks arising from the use of paid services shall be borne by you, and we do not make any guarantees about the results of service use.</li></ul><h2 id="_9-other-terms" tabindex="-1">9. Other Terms <a class="header-anchor" href="#_9-other-terms" aria-label="Permalink to &quot;9. Other Terms&quot;">​</a></h2><ul><li>The formation, validity, interpretation, performance and dispute resolution of this agreement shall be governed by the laws of the People&#39;s Republic of China.</li><li>Any dispute arising from this agreement shall first be resolved through friendly negotiation between the parties; if the negotiation fails, either party has the right to file a lawsuit with the people&#39;s court with jurisdiction at the location of Vilinko Studio.</li><li>We have the right to modify this agreement according to changes in laws and regulations or business needs. The modified agreement shall take effect after being published. Your continued use of paid services means that you accept the modified agreement.</li><li>If you have any questions about this agreement, you can contact us via <a href="mailto:privacy@vilinko.com" target="_blank" rel="noreferrer">privacy@vilinko.com</a>.</li></ul><h2 id="links-to-third-party-policies" tabindex="-1">Links to Third-Party Policies <a class="header-anchor" href="#links-to-third-party-policies" aria-label="Permalink to &quot;Links to Third-Party Policies&quot;">​</a></h2><ul><li><a href="https://afdian.com/term" target="_blank" rel="noreferrer">Afadian Platform Service Terms</a></li></ul>',23)]))}const m=t(o,[["render",n]]);export{p as __pageData,m as default};
